import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api';
import { Line } from 'react-chartjs-2';
import { Activity } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      try {
        const res = await getFiles();
        if (mounted) setFiles(res.data || []);
      } catch (err) {
        if (err.name !== "CanceledError") console.error(err);
      }
    };

    load();

    return () => {
      mounted = false;
    };
  }, []);

  const getTotal = (f) => f?.metrics?.total_ms ?? f?.metrics?.total ?? 0;

  // ================= EXPORT DATASET =================
  const exportDataset = async () => {
    try {
      const token = localStorage.getItem("supabase.auth.token");

      const response = await fetch(
        "http://localhost:8000/api/v1/files/performance/export",
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "qs_vault_performance_dataset.csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      console.error("Dataset export failed:", err);
    }
  };

  // ================= EXISTING RSA vs PQC GRAPH =================
  const labels = files.map(f =>
    f.filename.length > 15 ? f.filename.slice(0, 15) + "..." : f.filename
  );

  const pqcData = files.map(f => f.mode === 'hybrid' ? getTotal(f) : null);
  const rsaData = files.map(f => f.mode !== 'hybrid' ? getTotal(f) : null);

  const lineChartData = {
    labels,
    datasets: [
      {
        label: 'Hybrid PQC',
        data: pqcData,
        borderColor: '#00ff9d',
        backgroundColor: '#00ff9d',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: true
      },
      {
        label: 'RSA Baseline',
        data: rsaData,
        borderColor: '#a855f7',
        backgroundColor: '#a855f7',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: true
      }
    ]
  };

  // ================= ML-KEM VARIANT AGGREGATION =================
  const pqcFiles = files.filter(f => f.mode === 'hybrid');

  const kem512 = pqcFiles.filter(f => f.metrics?.structural?.kem_variant === "ML-KEM-512");
  const kem768 = pqcFiles.filter(f => f.metrics?.structural?.kem_variant === "ML-KEM-768");
  const kem1024 = pqcFiles.filter(f => f.metrics?.structural?.kem_variant === "ML-KEM-1024");

  const sizeLabels = [...new Set(
    pqcFiles.map(f => f.metrics?.phase_1?.size_bytes)
  )].filter(Boolean).sort((a,b)=>a-b);

  const aggregateBySize = (arr) => {
    return sizeLabels.map(size => {
      const subset = arr.filter(f => f.metrics?.phase_1?.size_bytes === size);
      if (!subset.length) return null;
      return subset.reduce((a,f)=>a+getTotal(f),0) / subset.length;
    });
  };

  const kemComparisonData = {
    labels: sizeLabels.map(s => `${(s/1024).toFixed(0)} KB`),
    datasets: [
      {
        label: "ML-KEM-512",
        data: aggregateBySize(kem512),
        borderColor: "#00ff9d",
        backgroundColor: "#00ff9d",
        tension: 0.4,
        borderWidth: 2
      },
      {
        label: "ML-KEM-768",
        data: aggregateBySize(kem768),
        borderColor: "#ffa500",
        backgroundColor: "#ffa500",
        tension: 0.4,
        borderWidth: 2
      },
      {
        label: "ML-KEM-1024",
        data: aggregateBySize(kem1024),
        borderColor: "#ff3b3b",
        backgroundColor: "#ff3b3b",
        tension: 0.4,
        borderWidth: 2
      }
    ]
  };

  const hybrid = files.filter(f => f.mode === 'hybrid');
  const rsa = files.filter(f => f.mode !== 'hybrid');

  const avgPqc = hybrid.length
    ? (hybrid.reduce((a, f) => a + getTotal(f), 0) / hybrid.length).toFixed(2)
    : "0.00";

  const avgRsa = rsa.length
    ? (rsa.reduce((a, f) => a + getTotal(f), 0) / rsa.length).toFixed(2)
    : "0.00";

  return (
    <div className="p-8 flex-1 min-h-0 space-y-6 overflow-y-auto custom-scrollbar">

      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <div>
          <h2 className="text-2xl font-bold text-white">Performance Monitor</h2>
          <p className="text-gray-500 text-xs font-mono uppercase">
            Comparative Analysis Engine
          </p>
        </div>

        <div className="text-right">
          <span className="text-xs text-gray-500 uppercase">Total Files</span>
          <p className="text-2xl font-mono text-white">{files.length}</p>

          <button
            onClick={exportDataset}
            className="mt-3 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-xl text-xs"
          >
            Export Dataset (CSV)
          </button>
        </div>
      </div>

      {/* EXISTING GRAPH */}
      <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
        <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2">
          <Activity size={16} /> Encryption Latency Timeline
        </h3>

        <div className="h-80">
          <Line
            data={lineChartData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                legend: { labels: { color: '#fff' } }
              },
              scales: {
                x: {
                  title: {
                    display: true,
                    text: 'Encrypted Files',
                    color: '#aaa'
                  },
                  ticks: { color: '#888' },
                  grid: { display: false }
                },
                y: {
                  beginAtZero: true,
                  title: {
                    display: true,
                    text: 'Encryption Latency (ms)',
                    color: '#aaa'
                  },
                  ticks: { color: '#888' },
                  grid: { color: '#222' }
                }
              }
            }}
          />
        </div>
      </div>

      {/* NEW ML-KEM VARIANT GRAPH */}
      <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
        <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2">
          <Activity size={16} /> ML-KEM Variant Comparison (Mean Latency)
        </h3>

        <div className="h-80">
          <Line
            data={kemComparisonData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                legend: { labels: { color: '#fff' } }
              },
              scales: {
                x: {
                  title: {
                    display: true,
                    text: 'File Size',
                    color: '#aaa'
                  },
                  ticks: { color: '#888' },
                  grid: { display: false }
                },
                y: {
                  beginAtZero: true,
                  title: {
                    display: true,
                    text: 'Mean Encryption Latency (ms)',
                    color: '#aaa'
                  },
                  ticks: { color: '#888' },
                  grid: { color: '#222' }
                }
              }
            }}
          />
        </div>
      </div>

      {/* AVERAGES */}
      <div className="grid grid-cols-2 gap-4">
        <Card title="Average PQC" value={`${avgPqc} ms`} color="text-neon-green"/>
        <Card title="Average RSA" value={`${avgRsa} ms`} color="text-purple-400"/>
      </div>

      {/* PER FILE METRICS — UNCHANGED */}
      <div className="space-y-3">
        {files.map(file => {
          const m = file.metrics || {};
          const p1 = m.phase_1 || {};
          const p2 = m.phase_2 || {};
          const p3 = m.phase_3 || {};
          const p4 = m.phase_4 || {};
          const p5 = m.phase_5 || {};
          const d = m.derived || {};
          const e = m.efficiency || {};
          const x = m.expansion || {};
          const s = m.structural || {};

          return (
            <div key={file.id} className="bg-black/40 border border-gray-800 p-4 rounded">
              <div className="flex justify-between mb-3">
                <span className="text-white font-bold">{file.filename}</span>
                <span className={file.mode === 'hybrid' ? 'text-neon-green' : 'text-purple-400'}>
                  {file.mode}
                </span>
              </div>

              <div className="grid grid-cols-3 gap-2 text-xs font-mono">
                <Metric label="Size" value={`${p1.size_bytes ?? "N/A"} B`} />
                <Metric label="Encap" value={p2.encap_us != null ? `${p2.encap_us.toFixed(0)} us` : "N/A"} />
                <Metric label="AES" value={p4.aes_enc_ms != null ? `${p4.aes_enc_ms.toFixed(2)} ms` : "N/A"} />
                <Metric label="Total" value={`${getTotal(file)} ms`} highlight />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const Card = ({ title, value, color }) => (
  <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
    <span className="text-gray-400">{title}</span>
    <span className={`font-bold ${color}`}>{value}</span>
  </div>
);

const Metric = ({ label, value, highlight }) => {
  let color = highlight ? "text-white" : "text-gray-400";
  return (
    <div className={`p-2 rounded border border-gray-800 ${color}`}>
      {label}: <span className="ml-1">{value}</span>
    </div>
  );
};

export default Performance;
